from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize a list to store distinct groups

    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while j < len(paren_string):
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                if count == 0:
                    groups.append(paren_string[i:j+1])  # Step 2: Identify distinct groups of nested parentheses
                    i = j + 1
                    break
                j += 1
        else:
            i += 1

    return groups  # Step 3: Separate each group into individual strings and return them as a list

